create extension if not exists pgcrypto;
create type public.platform as enum ('tiktok','instagram','manual','demo');
create type public.download_state as enum ('NOT_DOWNLOADED','DOWNLOADING','DOWNLOADED','FAILED');
create type public.import_status as enum ('PENDING','RUNNING','COMPLETED','FAILED');
create table public.profiles (id uuid primary key references auth.users on delete cascade, email text, display_name text, avatar_url text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.social_accounts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, platform public.platform not null, platform_user_id text, access_token_encrypted text, refresh_token_encrypted text, token_expires_at timestamptz, created_at timestamptz default now(), unique(user_id,platform));
create table public.tracks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, platform public.platform not null, platform_post_id text, platform_audio_id text, source_url text not null, title text not null, creator_name text, thumbnail_url text, remote_audio_url text, duration_ms integer default 0, local_file_path text, download_state public.download_state default 'NOT_DOWNLOADED', file_size bigint, is_favorite boolean default false, play_count integer default 0, created_at timestamptz default now(), updated_at timestamptz default now(), unique(user_id,platform,source_url));
create table public.source_posts (id uuid primary key default gen_random_uuid(), track_id uuid not null references public.tracks on delete cascade, platform_post_id text, source_url text not null, creator_name text, caption text, created_at timestamptz default now());
create table public.playlists (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, name text not null, cover_url text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.playlist_tracks (playlist_id uuid references public.playlists on delete cascade, track_id uuid references public.tracks on delete cascade, position integer not null check(position>=0), added_at timestamptz default now(), primary key(playlist_id,track_id), unique(playlist_id,position));
create table public.playback_history (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, track_id uuid references public.tracks on delete cascade, played_at timestamptz default now(), position_ms integer default 0);
create table public.import_jobs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, type text not null, platform public.platform, status public.import_status default 'PENDING', progress integer default 0 check(progress between 0 and 100), error text, created_at timestamptz default now(), updated_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.social_accounts enable row level security; alter table public.tracks enable row level security; alter table public.source_posts enable row level security; alter table public.playlists enable row level security; alter table public.playlist_tracks enable row level security; alter table public.playback_history enable row level security; alter table public.import_jobs enable row level security;
create policy "own profiles" on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy "own accounts" on public.social_accounts for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own tracks" on public.tracks for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own source posts" on public.source_posts for all using(exists(select 1 from public.tracks t where t.id=track_id and t.user_id=auth.uid())) with check(exists(select 1 from public.tracks t where t.id=track_id and t.user_id=auth.uid()));
create policy "own playlists" on public.playlists for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own playlist tracks" on public.playlist_tracks for all using(exists(select 1 from public.playlists p where p.id=playlist_id and p.user_id=auth.uid())) with check(exists(select 1 from public.playlists p where p.id=playlist_id and p.user_id=auth.uid()));
create policy "own history" on public.playback_history for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own imports" on public.import_jobs for all using(user_id=auth.uid()) with check(user_id=auth.uid());
